import { test, expect } from '@playwright/test';

test.describe('Internal Links Open in Same Tab', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/page-with-internal-links');
  });

  test('should open internal links in the same tab', async ({ page }) => {
    // Verify the page is loaded
    await expect(page).toHaveURL(/page-with-internal-links/);

    // Get the internal link button by role
    const internalLinkButton = page.getByRole('button', { name: /go to about page/ });
    await expect(internalLinkButton).toBeVisible();

    // Get the internal link by role
    const internalLink = page.getByRole('link', { name: /about us/ });
    await expect(internalLink).toBeVisible();

    // Get the internal link by role
    const contactLink = page.getByRole('link', { name: /contact us/ });
    await expect(contactLink).toBeVisible();

    // Click the internal link
    await internalLink.click();

    // Verify the URL changed to the about page
    await expect(page).toHaveURL(/page\/about/);

    // Verify the page content has loaded
    const aboutHeading = page.getByRole('heading', { name: /about us/ });
    await expect(aboutHeading).toBeVisible();

    // Verify the back button is available
    const backButton = page.getByRole('button', { name: /back to home/ });
    await expect(backButton).toBeVisible();

    // Click the back button
    await backButton.click();

    // Verify the URL is back to the original page
    await expect(page).toHaveURL(/page\/with-internal-links/);
  });

  test('should not open internal links in a new tab', async ({ page }) => {
    // Verify the page is loaded
    await expect(page).toHaveURL(/page\/with-internal-links/);

    // Get the internal link by role
    const internalLink = page.getByRole('link', { name: /contact us/ });
    await expect(internalLink).toBeVisible();

    // Get the external link by role
    const externalLink = page.getByRole('link', { name: /external site/ });
    await expect(externalLink).toBeVisible();

    // Click the internal link
    await internalLink.click();

    // Verify the URL changed to the contact page
    await expect(page).toHaveURL(/page\/contact/);

    // Verify the contact page heading is visible
    const contactHeading = page.getByRole('heading', { name: /contact us/ });
    await expect(contactHeading).toBeVisible();

    // Verify the page title reflects the contact page
    await expect(page).toHaveTitle(/contact us/);

    // Verify the external link still exists and is accessible
    await expect(externalLink).toBeVisible();

    // Click the external link
    await externalLink.click();

    // Verify the external link opens in a new tab
    const newTab = page.context().pages().find((p) => p.url().includes('external-site.com'));
    await expect(newTab).toBeDefined();

    // Verify the original page is still open
    await expect(page).toHaveURL(/page\/contact/);
  });
});
